const asNumber = (value) => {
  if (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  ) {
    return null;
  }

  const n = Number(
    String(value).replace(/[$,]/g, '').trim()
  );

  return Number.isFinite(n) ? n : null;
};

const normalizeText = (value) =>
  String(value ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

return $input.all().map((item) => {
  const d = item.json;

  const revenue = asNumber(d.revenueUsd);
  const employees = asNumber(d.employeeCount);
  const growth = asNumber(d.growthScore);
  const delta = asNumber(d.growthScore90DayDelta);

  const direction = String(
    d.growthDirection ?? ''
  ).toLowerCase();

  const products = Array.isArray(d.detectedProducts)
    ? d.detectedProducts.join(', ').toLowerCase()
    : String(d.detectedProducts ?? '').toLowerCase();

  const missing = [];
  const scoringNotes = [];

  const breakdown = {
    industry: 0,
    revenue: 0,
    employees: 0,
    growth: 0,
    technology: 0
  };

  // =====================================
  // 1. INDUSTRY — MAX 25 POINTS
  // =====================================

  const classification = d.output?.category
    ? d.output
    : (d.output?.output ?? {});

  const category = String(
    classification.category ?? 'UNKNOWN'
  ).trim().toUpperCase();

  const industryScores = {
    B2B_SAAS: 25,
    B2B_SOFTWARE: 20,
    MIXED_TECH: 10,
    NOT_ICP: 0
  };

  const validCategory =
    Object.prototype.hasOwnProperty.call(
      industryScores,
      category
    );

  const websiteEvidence =
    Array.isArray(d.websiteEvidence)
      ? d.websiteEvidence
      : [];

  const hasWebsiteEvidence = websiteEvidence.some(
    (page) =>
      typeof page?.content === 'string' &&
      page.content.trim().length > 0
  );

  const evidenceText = [
    d.companyDescription ?? '',
    ...websiteEvidence.map(
      (page) =>
        `${page.title ?? ''} ${page.content ?? ''}`
    )
  ].join(' ');

  const quote = normalizeText(
    classification.evidenceQuote
  );

  const quoteSupported =
    quote.length > 0 &&
    normalizeText(evidenceText).includes(quote);

  // Award category points independently
  // of quotation-formatting differences.
  if (validCategory && hasWebsiteEvidence) {
    breakdown.industry = industryScores[category];
  }

  // Validate whether the classification
  // is sufficiently supported.
  const industryVerified =
    validCategory &&
    hasWebsiteEvidence &&
    classification.needsReview === false &&
    quoteSupported;

  if (!industryVerified) {
    missing.push('industryVerification');

    scoringNotes.push(
      'Industry classification needs review.'
    );

    if (!hasWebsiteEvidence) {
      scoringNotes.push(
        'No usable official website evidence.'
      );
    }

    if (!quoteSupported) {
      scoringNotes.push(
        'AI supporting quote not found in supplied evidence.'
      );
    }
  }

  scoringNotes.push(
    `AI business model category: ${category}`
  );

  // Clay's raw industry remains available
  // in d.industry for auditing.
  // It does not determine the ICP category
  // or automatically invalidate verification.

  // =====================================
  // 2. REVENUE — MAX 25 POINTS
  // =====================================

  const revenueUnknown =
    revenue === null ||
    revenue <= 0 ||
    String(d.revenueStatus ?? '')
      .toLowerCase() === 'unknown';

  if (revenueUnknown) {
    missing.push('revenue');
  } else if (revenue > 10000000) {
    breakdown.revenue = 25;
  } else if (revenue >= 5000000) {
    breakdown.revenue = 15;
  } else if (revenue >= 1000000) {
    breakdown.revenue = 5;
  }

  // =====================================
  // 3. EMPLOYEES — MAX 20 POINTS
  // =====================================

  if (employees === null || employees <= 0) {
    missing.push('employeeCount');
  } else if (
    employees >= 50 &&
    employees <= 2000
  ) {
    breakdown.employees = 20;
  } else if (
    (employees >= 20 && employees < 50) ||
    (employees > 2000 && employees <= 5000)
  ) {
    breakdown.employees = 10;
  }

  // =====================================
  // 4. GROWTH — MAX 15 POINTS
  // =====================================

  if (
    growth === null ||
    growth < 0 ||
    growth > 100
  ) {
    missing.push('growthScore');
  } else if (
    growth >= 75 &&
    delta !== null &&
    delta > 0 &&
    direction.includes('grow')
  ) {
    breakdown.growth = 15;
  } else if (
    growth >= 60 &&
    (delta === null || delta >= 0) &&
    !/\b(declin|shrink|contract)/.test(direction)
  ) {
    breakdown.growth = 10;
  } else if (growth >= 40) {
    breakdown.growth = 5;
  }

  // =====================================
  // 5. CRM TECHNOLOGY — MAX 15 POINTS
  // =====================================

  const verifiedCRM =
    /\b(salesforce\s*(sales cloud|crm)|crm\s*salesforce|hubspot\s*(crm|sales hub)|crm\s*hubspot)\b/
      .test(products);

  if (!products.trim()) {
    missing.push('detectedProducts');
  } else if (verifiedCRM) {
    breakdown.technology = 15;
  }

  // =====================================
  // FINAL SCORE
  // =====================================

  const total = Object.values(breakdown)
    .reduce((sum, points) => sum + points, 0);

  const fitTier =
    total >= 80 ? 'High' :
    total >= 60 ? 'Medium' : 'Low';

  const missingSignals = [...new Set(missing)];

  const scoreStatus =
    missingSignals.length > 0
      ? 'Provisional'
      : 'Complete';

  return {
    json: {
      ...d,

      icpScore: total,
      fitTier,

      icpBreakdown: breakdown,

      scoreStatus,
      missingSignals,

      industryClassification: category,
      industryVerified,

      industryConfidence:
        asNumber(classification.confidence),

      scoringNotes
    }
  };
});

