const company = $('Normalize Enriched Data').first().json;
const results = $input.first().json.results ?? [];

const domain = String(company.domain ?? '')
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

const relevant = results.filter(page => {
  const url = String(page.url ?? '');
  const host = (url.match(/^https?:\/\/([^/]+)/i) ?? [,''])[1]
    .toLowerCase().replace(/^www\./, '');

  const official = host === domain ||
    host.endsWith('.' + domain);

  const unwanted = /\/(careers?|jobs?|hiring)(\/|$|\?)/i.test(url) ||
    /\b(careers|job openings|hiring)\b/i.test(page.title ?? '');

  return official && !unwanted;
});

const priority = /\/(business|products?|solutions?|enterprise|pricing|platform|services)(\/|$)/i;

relevant.sort((a, b) =>
  Number(priority.test(b.url)) - Number(priority.test(a.url))
);

const websiteEvidence = relevant.slice(0, 3).map(page => ({
  url: page.url,
  title: page.title,
  content: String(page.content ?? '').slice(0, 1800)
}));

return [{
  json: {
    ...company,
    websiteEvidence,
    evidenceStatus: websiteEvidence.length
      ? 'Available'
      : 'Needs Research'
  }
}];
